-- ===========================================
-- MO, IL and IA 2026-27 waterfowl seasons, hand-entered from each agency (drafted 2026-11-11)
--
-- These three states had survey counts but no season rows, so the Map page drew their zones as
-- outlines only. Zone names match the Map page's zone shapes (scripts/zones/README.md):
-- MO North/Middle/South Zone; IL and IA North/Central/South Zone; plus Statewide.
--
-- Verified against:
--   MO  MDC season pages, read 2026-11-11 (one page per season; each row's source_url):
--       https://mdc.mo.gov/hunting-trapping/seasons/ducks-coots-hunting-north-zone (and -middle-, -south-)
--       .../ducks-coots-geese-hunting-youth-{north,middle,south}-zone, .../teal-hunting,
--       .../ducks-coots-mergansers-falconry, .../early-canada-goose-brant-hunting,
--       .../goose-canada-brant-white-fronted-snow-rosss-hunting, .../light-goose-conservation-order
--   IL  IDNR 2026-2027 waterfowl insert card ("Printed by the Authority of the State of Illinois
--       DNR-ORC-HY26-27, 07/26"), on HuntIllinois:
--       https://v3-wp.huntillinois.org/wp-content/uploads/2026/08/InsertCard.pdf
--       Its table cells overlap in the PDF; rows were read by word position and cross-checked
--       against the plain-text extraction. Every zone's duck days total 60 and its scaup
--       first-15/remaining-45 split lines up with the duck dates.
--   IA  Iowa DNR 2026-27 Hunting, Trapping & Migratory Game Bird Regulations, p. 10
--       (https://www.iowadnr.gov/media/1700/download), and the same dates on
--       https://www.iowadnr.gov/things-do/hunting-trapping/types-hunting-trapping/migratory-game-bird-hunting
--
-- Choices to confirm before applying:
--   IA  Canada goose cap. The booklet's text says no more than 2 Canada geese in the first
--       segment and 3 from the second; its season table prints "Begin 3 Canada goose bag limit"
--       beside the third segment. Entered per the text (2 in segment 1, 3 in segments 2 and 3),
--       and the rows' notes say so.
--   IA  Scaup. DNR prints the day the 2-a-day limit starts (Oct. 19 North, Oct. 26 Central,
--       Nov. 2 South: 15 calendar days after opening, not 15 hunting days). Entered as printed.
--   IL  The card gives no youth age; the rows point to the IDNR digest.
--
-- Model: same as scripts/waterfowl-seasons-2026-27-ar-ks-nm-ok.sql. One row per season segment;
-- seasons covering every duck hang off mallard with metadata.appliesTo = 'ducks' and
-- bag_limit.speciesLimits for the caps inside the aggregate. Scaup have their own rows because
-- their limit changes partway through each zone's season (as in the Louisiana script). Teal and
-- light-goose rows are repeated per species (blue-/green-winged teal; snow/Ross's geese).
-- Possession: 3x daily (the agencies' own rule for all three), none for light geese.
--
-- Not included (no species row): coots, mergansers (both in the duck bag notes), brant, black
-- ducks (in the notes), rails, snipe, woodcock, doves; Iowa's September metro Canada goose
-- seasons (designated city zones the map doesn't draw); the goose part of Missouri's youth
-- days (the youth rows are duck rows, as for every other state).
-- No existing rows: there were 0 year=2026 seasons for MO, IL and IA when this was drafted.
-- Rows are generated from one table of dates per state; edit this file directly if a date
-- changes (each row stands alone).
-- ===========================================
\set ON_ERROR_STOP on
BEGIN;

DELETE FROM seasons se USING states s
WHERE se.state_id = s.id AND s.code IN ('MO', 'IL', 'IA') AND se.year = 2026;

WITH
bags(key, b, r) AS (VALUES
  ('MO', jsonb_build_object('daily', 6, 'possession', 18,
     'speciesLimits', jsonb_build_object('mallard', 4, 'wood-duck', 3, 'pintail', 3, 'redhead', 2, 'canvasback', 2, 'scaup', 2, 'mottled-duck', 1),
     'notes', 'No more than 2 of the 4 mallards may be female; 2 black ducks; 2 hooded mergansers. Scaup: 2 a day the first 45 days, 1 a day the last 15. Coots 15 (45 possession).'),
   '6 ducks: no more than 4 mallards (2 female), 3 wood ducks, 3 pintails, 2 redheads, 2 canvasbacks, 2 black ducks, 2 hooded mergansers, 1 mottled duck and 2 scaup (1 for the last 15 days). Coots: 15. Possession 18.'),
  ('IL', jsonb_build_object('daily', 6, 'possession', 18,
     'speciesLimits', jsonb_build_object('mallard', 4, 'wood-duck', 3, 'pintail', 3, 'redhead', 2, 'canvasback', 2, 'mottled-duck', 1),
     'notes', 'No more than 2 of the 4 mallards may be hens; 2 black ducks. Scaup: 1 a day the first 15 days in each zone, then 2. Mergansers 5 (2 hooded), not counted toward ducks. Coots 15 (45 possession). Possession is 3x daily by species and sex.'),
   '6 ducks: no more than 4 mallards (2 hens), 3 wood ducks, 3 pintails, 2 redheads, 2 canvasbacks, 2 black ducks, 1 mottled duck, and scaup 1 a day the first 15 days then 2. Mergansers: 5 (2 hooded), in addition. Coots: 15. Possession three times the daily limit.'),
  ('IA', jsonb_build_object('daily', 6, 'possession', 18,
     'speciesLimits', jsonb_build_object('mallard', 4, 'wood-duck', 3, 'pintail', 3, 'redhead', 2, 'canvasback', 2),
     'notes', 'No more than 2 of the 4 mallards may be female; 2 black ducks. Scaup: 1 a day until Oct. 19 (North), Oct. 26 (Central) or Nov. 2 (South), then 2. Mergansers 5 (2 hooded). Coots 15. Possession 3x daily.'),
   '6 ducks: no more than 4 mallards (2 female), 3 wood ducks, 3 pintails, 2 redheads, 2 black ducks and 2 canvasbacks; scaup 1 a day at first, then 2 (from Oct. 19 North, Oct. 26 Central, Nov. 2 South). Mergansers: 5 (2 hooded). Coots: 15. Possession three times the daily limit.')
),
hours(code, h) AS (VALUES
  ('MO', '{"start": "one-half hour before sunrise", "end": "sunset"}'::jsonb),
  ('IL', '{"start": "one-half hour before sunrise", "end": "sunset"}'::jsonb),
  ('IA', '{"start": "one-half hour before sunrise", "end": "sunset"}'::jsonb)
),
